"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "개들이 사라지자 여우들이 마구간 주위를 맴돈다. 초원으로 쫓아 버려라",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "멧돼지가 농부들의 수확물을 먹어 치운다. 비축 없는 겨울은 우리의 끝이다",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "초원 가장자리에서 분노의 돌이 빛난다. 그 분노가 짐승을 미치게 한다 – 부숴라",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "바오가 보내 줘서 다행이야. 도적들이 숲길의 상인을 모조리 습격해. 쫓아내 줘",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "이곳 멧돼지는 털 대신 가시가 났다. 우리 덫을 – 덫꾼까지 – 찢어 버린다",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "숲 깊은 곳에서 거대 거미가 길 위에 거미줄을 친다. 필요하면 태워 버려라",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "숲 한가운데 가시의 돌이 자란다. 그 덩굴이 모든 나무를 질식시킨다. 파괴하라",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "하겐이 보냈나? 그럼 와, 오크들이 벌써 울타리 앞이야. 놈들의 군대를 약화시켜",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "오크들은 하이에나를 개처럼 길러 정찰병에게 풀어놓는다. 무리를 처리해라",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "이드리스가 보냈나? 신들이 사흐라를 돌보시는구나. 코브라가 모든 물가에 도사리고 있어",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "저 딸랑거리는 소리 들려? 방울뱀이야. 수백 마리. 대상들이 더는 길을 나서지 못해",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "서리 봉우리에서 집채만 한 예티가 목격됐어. 증거로 털가죽을 가져와",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "추위가 물러가지 않으면서 매머드가 날뛴다. 우리 저장 오두막을 짓밟고 있어",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "침묵의 돌이 선 곳에서는 모든 노래가 멎는다. 정상에 소리를 되찾아라",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "마지막이자 가장 강력한 영혼석. 파괴하면 돌들이 더 이상 자라지 않는다",
