"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "뼈 부르는 자들이 노래로 모래에서 뼈를 불러낸다. 노래가 없으면 망자는 누워 있다",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "모래 언덕에서 검은 돌 두 개가 솟아 있고 뼈가 그 주위에 모인다. 중심을 빼앗아라",
"Bleiche Stachel": "창백한 침",
"Die Knochenhauptmänner": "뼈 대장들",
