"Ein Stein der Asche verbrennt die Wüste von innen. Lösch ihn aus, bevor nur Staub bleibt": "재의 돌이 사막을 안에서부터 태운다. 먼지만 남기 전에 꺼라",
"Rot am Horizont": "지평선의 붉음",
