"Wargrudel der Steppe": "초원의 와르그 무리",
"Steppenwargs jagen in großen Rudeln durch das rote Gras. Jag das Rudel, bevor es uns jagt": "초원 와르그는 붉은 풀 속을 큰 무리로 사냥한다. 놈들이 우릴 사냥하기 전에 먼저 사냥해라",
"Blutdämonen": "피의 악마",
"Aus den roten Tümpeln steigen Blutdämonen. Treib sie zurück in die Tiefe": "붉은 웅덩이에서 피의 악마가 솟아오른다. 깊은 곳으로 돌려보내라",
"Die Steine der Glut heizen die Tümpel auf, bis sie kochen. Lösche sie aus": "불씨의 돌이 웅덩이를 끓을 때까지 데운다. 꺼라",
"Blutmäuler": "피아가리들",
"Blutmäuler bewachen die Tümpel der Dämonen. Wer sie besiegt, kann den Quellen nahe kommen": "피아가리가 악마의 웅덩이를 지킨다. 그들을 쓰러뜨려야 샘에 다가갈 수 있다",
