"Fügt einen zufälligen Bonus hinzu, bis zum {0}. Bonus": "무작위 보너스 추가, 최대 {0}번째 보너스까지",
"Fügt den {0}. Bonus hinzu. Der Gegenstand braucht dafür genau {1} Boni": "{0}번째 보너스 추가. 아이템에 보너스가 정확히 {1}개 있어야 합니다",
"Würfelt die Boni {0} bis {1} komplett neu aus. Die Anzahl bleibt gleich": "보너스 {0}~{1}을 완전히 다시 굴립니다. 개수는 그대로",
