"Wolfsplage": "늑대 재앙",
"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen": "늑대들이 대담해지고 있다. 성문에 닿기 전에 무리를 줄여라",
"Verirrte Hirsche": "길 잃은 사슴",
"Der Alpha": "우두머리",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel": "늑대 뒤에는 우두머리 늑대들이 있다. 그들이 없으면 무리는 흩어진다",
"Keiler in den Rüben": "비트밭의 멧돼지",
"Auf in den Dunkelwald": "어둠의 숲으로",
"Banditen im Dunkelwald": "어둠의 숲의 도적",
"Schützen im Dickicht": "덤불 속 궁수",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter": "도적들이 나무 위에서 움직이는 모든 것을 쏜다. 끌어내려라",
"Netz der Spinnen": "거미줄",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie": "탐욕의 돌 두 개가 금이 도둑을 부르듯 도적을 끌어들인다. 부숴라",
"Lautlose Jäger": "소리 없는 사냥꾼",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie": "스라소니가 아무도 모르게 정찰병을 덮친다. 그들보다 더 경계하라",
"Der Banditenfürst": "도적 두목",
"Der Braunbär": "불곰",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig": "불곰 무리가 나무꾼 길을 차지했다. 강하니 조심하라",
"Krieg in der Rostschlucht": "녹슨 협곡의 전쟁",
"Orks vor der Talwacht": "계곡 초소 앞의 오크",
"Hyänen der Orks": "오크의 하이에나",
"Die Schamanen": "주술사들",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut": "주술사들이 계곡에 저주를 건다. 그들이 없으면 오크는 용기를 잃는다",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen": "오크는 검은 돌을 숭배한다. 우상을 빼앗아라",
"Stachel im Sand": "모래 속의 독침",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten": "바위틈에 거대 전갈이 둥지를 틀었다. 독은 소도 마비시킨다. 틈을 청소하라",
"Der Ork-Hauptmann": "오크 대장",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie": "대장이 없으면 오크는 오합지졸일 뿐이다. 그들을 찾아라",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt": "재의 돌이 계곡을 안에서부터 태운다. 먼지만 남기 전에 꺼라",
"Asche über dem Ödland": "황무지 위의 재",
"Oger im Aschenfeld": "잿빛 들판의 오우거",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern": "스락이 너를 보낸 건 옳았다. 오우거가 매일 밤 야영지를 약탈한다. 막아라",
"Wargrudel": "와르그 무리",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel": "와르그는 오우거를 따라다니며 남은 걸 먹는다. 무리를 사냥하라",
"Dämonen im Ödland": "황무지의 악마",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe": "황무지의 균열에서 악마가 올라온다. 깊은 곳으로 돌려보내라",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus": "불씨의 돌이 황무지를 불태운다. 꺼라",
"Höllenhunde": "지옥견",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen": "머리 셋 달린 개가 균열을 지킨다. 그들을 쓰러뜨려야 균열에 다가갈 수 있다",
"Die Oase im Süden": "남쪽의 오아시스",
"Kobras in der Wüste": "사막의 코브라",
"Das Rasseln im Sand": "모래 속의 방울 소리",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder": "정글에선 비단뱀이 소를 통째로 조인다. 그곳에서 나무하는 자는 돌아오지 못한다",
"Schwarze Panther": "흑표범",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher": "나가의 표범이 밤에 사냥한다. 정글을 다시 안전하게 하라",
"Eis im Norden": "북쪽의 얼음",
"Eiswölfe": "얼음 늑대",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche": "하킴이 보냈나? 좋아. 얼음 늑대가 야영지를 맴돌며 모든 약점을 냄새 맡는다",
"Der Yeti": "예티",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie": "서리의 돌 두 개 때문에 정상이 녹지 않는다. 부숴라",
"Wilde Mammuts": "야생 매머드",
"Frostgeister": "서리 정령",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen": "눈보라 속에 정령이 떠돈다. 닿는 자는 안에서부터 얼어붙는다",
"Der Eiskönig": "얼음 왕",
"Nebel über dem Moor": "늪 위의 안개",
"Das Totenmoor": "죽음의 늪",
"Moorwölfe": "늪 늑대",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest": "이곳 늑대는 반쯤 죽었는데도 사냥을 멈추지 않는다. 끝장내라",
"Die Sumpfhexen": "늪의 마녀들",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu": "마녀들이 진흙에서 망자를 불러낸다. 그들이 없으면 무덤은 닫힌 채로 남는다",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr": "부패의 돌 두 개가 물을 오염시킨다. 살아 있는 것은 더 이상 자라지 않는다",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller": "구울은 마녀가 깨운 것을 먹어 치운다. 빠르고 굶주렸다. 더 빨라져라",
"Donner in der Klamm": "협곡의 천둥",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke": "오스윈이 보냈나? 트롤이 협곡을 포위했다. 우리의 힘을 보여 줘라",
"Harpyien": "하피들",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft": "고개를 오르는 자에게 하피가 덮친다. 하늘에서 떨어뜨려라",
"Die Minotauren": "미노타우로스들",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf": "미노타우로스가 뿔을 숙이고 성문에 돌진한다. 막아라",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz": "핏빛 돌이 바위에서 자라난다. 고통을 먹고 산다",
"Erwachte Titanen": "깨어난 타이탄",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer": "타이탄 능선에서 바위 타이탄이 일어선다. 다시 멈추게 하라 – 영원히",
"Der Berg brennt": "산이 불탄다",
